#[verifier::requires(v.len() > 0)]
#[verifier::requires(is_sorted(v@))]
#[verifier::requires(contains(v@, k))]
#[verifier::ensures(|ret: usize| ret < v.len() && v[ret] == k)]
fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low: usize = 0;
    // safe because v.len() > 0
    let mut high: usize = v.len() - 1;

    #[verifier::invariant(low <= v.len())]
    #[verifier::invariant(high < v.len())]
    #[verifier::invariant(contains(v@[low..(high+1)], k))]
    #[verifier::decreases((high as int) - (low as int) + 1)]
    while low <= high {
        // Compute mid without overflow
        let mid = low + (high - low) / 2;
        match v[mid].cmp(&k) {
            Ordering::Equal => {
                // we found it
                return mid;
            }
            Ordering::Less => {
                // k must be to the right of mid
                low = mid + 1;
            }
            Ordering::Greater => {
                // k must be to the left of mid
                // Note: mid == 0 cannot happen under our invariant
                // because then v@[0] > k would contradict contains(...)
                if mid == 0 {
                    // unreachable under our preconditions, but keep it to avoid underflow
                    break;
                }
                high = mid - 1;
            }
        }
    }

    // By our pre‐ and loop‐invariants this point is unreachable:
    verifier::assert(false);
    // satisfy the Rust type checker:
    unreachable!()
}

